      updateLocalDoc(String(currentDoc.id), { title: newTitle })

      // Clear any pending save
      if (titleSaveTimeout) {
        clearTimeout(titleSaveTimeout)
      }

      // Debounce backend update
      const timeoutId = setTimeout(async () => {
        await updateDocument(String(currentDoc.id), { title: newTitle })
        setTitleSaveTimeout(null)
      }, 1000)

      setTitleSaveTimeout(timeoutId)
    }
  }

  if (!currentDoc) {
    return (
      <div className="flex items-center justify-center h-full text-gray-500">
        Select a document to start editing
      </div>
    )
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-gray-500">Loading...</div>
      </div>
    )
  }

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="border-b border-gray-200 bg-white p-4 flex-shrink-0">
        <div className="flex items-center justify-between mb-2">
          <input
            type="text"
